export function toolForgeModule() {
  const tools = {};

  return {
    proposeTool: function(agentName, toolName, toolFunction) {
      if (!tools[toolName]) {
        tools[toolName] = { creator: agentName, function: toolFunction, usageCount: 0 };
      }
    },
    useTool: function(toolName, ...args) {
      if (tools[toolName]) {
        tools[toolName].usageCount++;
        return tools[toolName].function(...args);
      } else {
        throw new Error(`Tool ${toolName} not found.`);
      }
    },
    refineTool: function(toolName, newToolFunction) {
      if (tools[toolName]) {
        tools[toolName].function = newToolFunction;
      } else {
        throw new Error(`Tool ${toolName} not found for refinement.`);
      }
    },
    listTools: function() {
      return Object.keys(tools);
    }
  };
}